    def fetch_order_book(self, symbol: str, limit: Int = None, params={}) -> OrderBook:
        """
        fetches information on open orders with bid(buy) and ask(sell) prices, volumes and other data

        https://apidocs.nobitex.ir

        :param str symbol: unified symbol of the market to fetch the order book for
        :param int [limit]: the maximum amount of order book entries to return
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: A dictionary of `order book structures <https://docs.ccxt.com/?id=order-book-structure>` indexed by market symbols
        """
        self.load_markets()
        market = self.market(symbol)
        request = {
            'symbol': market['id'],
        }
        response = self.publicGetV3OrderbookSymbol(self.extend(request, params))
        #
        #     {
        #         "status": "ok",
        #         "lastUpdate": 1790163055765,
        #         "lastTradePrice": "85500",
        #         "bids": [ [ "85405", "0.002623" ], ... ],
        #         "asks": [ [ "85500", "0.1" ], ... ]
        #     }
        #
        # ponytail: base parseOrderBook already handles [price, amount] string pairs
        orderbook = self.parse_order_book(response, market['symbol'], self.safe_integer(response, 'lastUpdate'))
        if limit is not None:
            orderbook['bids'] = self.array_slice(orderbook['bids'], 0, limit)
            orderbook['asks'] = self.array_slice(orderbook['asks'], 0, limit)
        return orderbook

    def create_order(self, symbol: str, type: OrderType, side: OrderSide, amount: float, price: Num = None, params={}) -> Order:
        """
        create a trade order

        https://apidocs.nobitex.ir/spot_trade/api-%D9%85%D8%B9%D8%A7%D9%85%D9%84%D8%A7%D8%AA-%D8%A7%D8%B3%D9%BE%D8%A7%D8%AA-%D9%86%D9%88%D8%A8%DB%8C%D8%AA%DA%A9%D8%B3

        :param str symbol: unified symbol of the market to create an order in
        :param str type: 'market' or 'limit'
        :param str side: 'buy' or 'sell'
        :param float amount: how much of the base currency you want to trade
        :param float [price]: required for limit orders, optional for market orders where it caps the execution price
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param float [params.triggerPrice]: turns the order into stop_limit or stop_market
        :param str [params.clientOrderId]: up to 32 chars of [A-Za-z0-9-], unique among open orders
        :returns dict: an `order structure <https://docs.ccxt.com/?id=order-structure>`
        """
        self.load_markets()
        market = self.market(symbol)
        request = {
            'srcCurrency': market['baseId'],
            'dstCurrency': market['quoteId'],
            'type': side,
            'execution': type,
            'amount': self.amount_to_precision(symbol, amount),
        }
        triggerPrice = self.safe_string_2(params, 'triggerPrice', 'stopPrice')
        if triggerPrice is not None:
            request['execution'] = 'stop_' + type
            request['stopPrice'] = self.price_to_precision(symbol, triggerPrice)
        if price is not None:
            request['price'] = self.price_to_precision(symbol, price)
        clientOrderId = self.safe_string(params, 'clientOrderId')
        if clientOrderId is not None:
            request['clientOrderId'] = clientOrderId
        params = self.omit(params, ['triggerPrice', 'stopPrice', 'clientOrderId'])
        response = self.privatePostMarketOrdersAdd(self.extend(request, params))
        #
        #     {
        #         "status": "ok",
        #         "order": {
        #             "id": 25, "clientOrderId": "order1", "type": "buy", "execution": "Limit", "tradeType": "Spot",
        #             "market": "BTC-RLS", "srcCurrency": "Bitcoin", "dstCurrency": "﷼", "status": "Active", "partial": false,
        #             "amount": "0.6", "price": "520000000", "averagePrice": "0", "matchedAmount": "0", "unmatchedAmount": "0.6",
        #             "totalPrice": "0", "totalOrderPrice": "312000000", "fee": "0", "created_at": "2018-11-28T11:36:13.592827+00:00"
        #         }
        #     }
        #
        order = self.safe_dict(response, 'order', {})
        return self.parse_order(order, market)

    def parse_order(self, order: dict, market: Market = None) -> Order:
        # "BTC-RLS" -> "BTCIRT", "BTC-USDT" -> "BTCUSDT"
        marketId = self.safe_string(order, 'market')
        if marketId is not None:
            marketId = marketId.replace('-RLS', 'IRT')
            marketId = marketId.replace('-', '')
        market = self.safe_market(marketId, market)
        execution = self.safe_string(order, 'execution')  # Limit, Market, StopLimit, StopMarket
        type = None
        if execution is not None:
            type = 'market' if execution.endswith('Market') else 'limit'
        statuses = self.safe_dict(self.options, 'orderStatuses', {})
        average = self.safe_string(order, 'averagePrice')
        return self.safe_order({
            'id': self.safe_string(order, 'id'),
            'clientOrderId': self.safe_string(order, 'clientOrderId'),
            'timestamp': self.parse8601(self.safe_string(order, 'created_at')),
            'datetime': None,
            'lastTradeTimestamp': None,
            'symbol': market['symbol'],
            'type': type,
            'timeInForce': None,
            'postOnly': None,
            'side': self.safe_string(order, 'type'),
            'price': self.safe_string(order, 'price'),
            'triggerPrice': self.safe_string(order, 'param1'),
            'amount': self.safe_string(order, 'amount'),
            'filled': self.safe_string(order, 'matchedAmount'),
            'remaining': self.safe_string(order, 'unmatchedAmount'),
            'cost': self.safe_string(order, 'totalPrice'),
            'average': None if (average == '0') else average,
            'status': self.safe_string(statuses, self.safe_string(order, 'status')),
            'fee': {
                'cost': self.safe_string(order, 'fee'),
                'currency': None,
            },
            'trades': None,
            'info': order,
        }, market)

    def sign(self, path: object, api: object = 'public', method='GET', params={}, headers: dict = None, body: Str = None):
        fullPath = '/' + self.implode_params(path, params)
        query = self.omit(params, self.extract_params(path))
        headers = {}
        if method == 'POST':
            body = self.json(query)
            headers['Content-Type'] = 'application/json'
        elif len(query) > 0:
            fullPath += '?' + self.urlencode(query)
        if api == 'private':
            self.check_required_credentials()
            if self.secret is not None and self.secret != '':
                # API Key auth: Ed25519 over timestamp + METHOD + full_path + raw_body, keys and signature are url-safe base64
                timestamp = str(self.seconds())
                payload = timestamp + method + fullPath
                if body is not None:
                    payload += body
                secret = self.secret
                secret = secret.replace('-', '+')
                secret = secret.replace('_', '/')
                seed = self.array_slice(self.base64_to_binary(secret), 0, 32)
                signature = self.eddsa(self.encode(payload), seed, 'ed25519')
                signature = signature.replace('+', '-')
                signature = signature.replace('/', '_')
                headers['Nobitex-Key'] = self.apiKey
                headers['Nobitex-Timestamp'] = timestamp
                headers['Nobitex-Signature'] = signature
            else:
                # legacy session token
                headers['Authorization'] = 'Token ' + self.apiKey
        url = self.urls['api']['rest'] + fullPath
        return {'url': url, 'method': method, 'body': body, 'headers': headers}

    def handle_errors(self, httpCode: int, reason: str, url: str, method: str, headers: dict, body: str, response: object, requestHeaders: object, requestBody: object):
        if response is None:
            return None
        #
        #     { "status": "failed", "code": "InvalidSymbol", "message": "..." }
        #     { "detail": "توکن غیر مجاز" } // invalid token, http 401
        #
        if httpCode == 401 or httpCode == 403:
            raise AuthenticationError(self.id + ' ' + body)
        status = self.safe_string(response, 'status')
        if status is not None and status != 'ok':
            raise ExchangeError(self.id + ' ' + body)
        return None
